/** Get the user's organization info and role */
getMyOrganization: protectedProcedure
  .query(async ({ ctx }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const result = await getUserOrganization(userId);
    if (!result) return null;
    return {
      orgId: result.org.id,
      orgName: result.org.name,
      orgSlug: result.org.slug,
      orgPlan: result.org.plan,
      myRole: result.role,
    };
  }),

/** Create a new organization */
createOrganization: protectedProcedure
  .input(z.object({
    name: z.string().min(2).max(256),
    slug: z.string().min(2).max(64).regex(/^[a-z0-9-]+$/, 'Slug must be lowercase alphanumeric with hyphens'),
  }))
  .mutation(async ({ ctx, input }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    try {
      const result = await createOrganization(userId, input.name, input.slug);
      return { success: true, orgId: result.orgId };
    } catch (error: unknown) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
    }
  }),

/** Get team members list with usage */
getTeamMembers: protectedProcedure
  .query(async ({ ctx }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) return { members: [], myRole: null };
    const members = await getTeamMembers(userOrg.org.id);
    return { members, myRole: userOrg.role };
  }),

/** Update a team member's role */
updateMemberRole: protectedProcedure
  .input(z.object({
    targetUserId: z.number(),
    newRole: z.enum(['admin', 'member']),
  }))
  .mutation(async ({ ctx, input }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) throw new TRPCError({ code: 'NOT_FOUND', message: 'No organization found' });
    if (!canManageTeam(userOrg.role)) {
      throw new TRPCError({ code: 'FORBIDDEN', message: 'Only admins can manage team roles' });
    }
    try {
      await updateMemberRole(userOrg.org.id, input.targetUserId, input.newRole, userId);
      return { success: true };
    } catch (error: unknown) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
    }
  }),

/** Remove a member from the team */
removeTeamMember: protectedProcedure
  .input(z.object({
    targetUserId: z.number(),
  }))
  .mutation(async ({ ctx, input }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) throw new TRPCError({ code: 'NOT_FOUND', message: 'No organization found' });
    if (!canManageTeam(userOrg.role)) {
      throw new TRPCError({ code: 'FORBIDDEN', message: 'Only admins can remove members' });
    }
    try {
      await removeMember(userOrg.org.id, input.targetUserId, userId);
      return { success: true };
    } catch (error: unknown) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
    }
  }),

/** Send a team invitation */
sendTeamInvitation: protectedProcedure
  .input(z.object({
    email: z.string().email(),
    role: z.enum(['admin', 'member']).default('member'),
  }))
  .mutation(async ({ ctx, input }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) throw new TRPCError({ code: 'NOT_FOUND', message: 'No organization found' });
    if (!canManageTeam(userOrg.role)) {
      throw new TRPCError({ code: 'FORBIDDEN', message: 'Only admins can send invitations' });
    }
    const planKey = await getUserPlanKey(userId);
    try {
      const result = await sendInvitation(userOrg.org.id, input.email, input.role, userId, planKey);

      // Send invitation email via Postmark
      const inviterName = ctx.user?.name || 'A team admin';
      const baseUrl = ctx.req?.headers?.origin || process.env.VITE_APP_URL || undefined;
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 7);

      sendInvitationEmail({
        recipientEmail: input.email,
        inviterName,
        orgName: userOrg.org.name,
        role: input.role,
        token: result.token,
        expiresAt,
      }, baseUrl).catch(err => {
        governanceLog.error('[sendTeamInvitation] Email send failed (non-blocking):', err);
      });

      return { success: true, invitationId: result.invitationId };
    } catch (error: unknown) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
    }
  }),

/** Get all invitations for the user's organization */
getTeamInvitations: protectedProcedure
  .query(async ({ ctx }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) return [];
    return getOrgInvitations(userOrg.org.id);
  }),

/** Revoke a pending invitation */
revokeTeamInvitation: protectedProcedure
  .input(z.object({
    invitationId: z.number(),
  }))
  .mutation(async ({ ctx, input }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) throw new TRPCError({ code: 'NOT_FOUND', message: 'No organization found' });
    if (!canManageTeam(userOrg.role)) {
      throw new TRPCError({ code: 'FORBIDDEN', message: 'Only admins can revoke invitations' });
    }
    try {
      await revokeInvitation(input.invitationId, userOrg.org.id, userId);
      return { success: true };
    } catch (error: unknown) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
    }
  }),

/** Accept a team invitation by token */
acceptTeamInvitation: protectedProcedure
  .input(z.object({
    token: z.string(),
  }))
  .mutation(async ({ ctx, input }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    try {
      const result = await acceptInvitation(input.token, userId);
      return { success: true, orgId: result.orgId, role: result.role };
    } catch (error: unknown) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
    }
  }),

/** Get seat allocation for the user's organization */
getTeamSeatAllocation: protectedProcedure
  .query(async ({ ctx }) => {
    const userId = ctx.user?.id;
    if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
    const userOrg = await getUserOrganization(userId);
    if (!userOrg) return null;
    const planKey = await getUserPlanKey(userId);
    return getSeatAllocation(userOrg.org.id, planKey);
  }),

// ========================================================================
// INVITATION LOOKUP (public — used by /join/:token page)
// ========================================================================

/** Look up an invitation by token (public, for the join page) */

