  /**
   * Instant domain scan — returns score + domain breakdown + fix pack
   * in a single call. No email, no signup, no friction.
   * This is the entry point for the frictionless first experience.
   */
  // Get scan usage info for the current user
  getScanUsage: protectedProcedure
    .query(async ({ ctx }) => {
      const usage = await getScanUsageInfo(ctx.user?.id ?? null);
      const gates = getFeatureGates(usage.planKey);
      return { usage, featureGates: gates };
    }),

  // Get feature gates for the current user
  getFeatureGatesInfo: protectedProcedure
    .query(async ({ ctx }) => {
      const planKey = await getUserPlanKey(ctx.user?.id ?? null);
      return getFeatureGates(planKey);
    }),

  quickScan: publicProcedure
    .input(z.object({
      domainUrl: z.string().min(3).max(512),
    }))
    .mutation(async ({ input, ctx }) => {
      // Resolve user plan for gating
      const userId = (ctx as unknown as Record<string, unknown>).user?.id ?? null;
      const planKey = await getUserPlanKey(userId);
      const gates = getFeatureGates(planKey);
      const usage = userId ? await getScanUsageInfo(userId) : null;
      let normalizedUrl = input.domainUrl.trim().toLowerCase();
      // Strip protocol for display, add for analysis
      const displayDomain = normalizedUrl.replace(/^https?:\/\//, '').replace(/\/$/, '');
      if (!normalizedUrl.startsWith('http')) {
        normalizedUrl = `https://${normalizedUrl}`;
      }

      // ── REAL ANALYSIS: Fetch actual content and run LLM governance review ──
      let report: { overallScore: number; domains: Array<{ domain: string; score: number; findings: number; topIssues: string[] }>; summary: string; recommendations: string[]; generatedAt: number };
=== 1900-1925 ===
    }),

  previewDigest: protectedProcedure
    .input(z.object({
      frequency: z.enum(['daily', 'weekly']).default('weekly'),
    }).optional())
    .query(async ({ ctx, input }) => {
      const userId = ctx.user?.id;
      if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
      const frequency = input?.frequency || 'weekly';
      const data = await aggregateDigestData(userId);
      const content = formatDigestContent(data, frequency);
      return { data, formattedContent: content };
    }),

  sendTestDigest: protectedProcedure
    .mutation(async ({ ctx }) => {
      const userId = ctx.user?.id;
      if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
      const prefs = await getDigestPreferences(userId);
      const frequency = prefs?.frequency || 'weekly';
      return sendDigestForUser(userId, frequency);
    }),

