/**
 * Policy Constraint Engine — Policy Registry
 * 
 * Loads policies from default pack and external JSON files.
 * Provides CRUD operations for policy management.
 * Caches policies in memory with file-system persistence.
 * 
 * Step 7 of PCE implementation.
 * Created: Mar 9, 2026
 */

import * as fs from 'fs';
import * as path from 'path';
import type { PolicyDefinition } from './policySchema';
import { DEFAULT_POLICIES } from './defaultPolicies';
import { governanceLog as log } from '../../_core/logger';

// ============================================================================
// REGISTRY STATE
// ============================================================================

const policyStore = new Map<string, PolicyDefinition>();
let initialized = false;

const POLICY_DIR = path.resolve(process.cwd(), 'governance-policies');

// ============================================================================
// INITIALIZATION
// ============================================================================

/**
 * Initialize the policy registry by loading defaults and external policies.
 */
export function initializePolicyRegistry(): void {
  if (initialized) return;

  // Load default policies
  for (const policy of DEFAULT_POLICIES) {
    policyStore.set(policy.id, { ...policy });
  }
  log.info(`[PolicyRegistry] Loaded ${DEFAULT_POLICIES.length} default policies`);

  // Load external policies from governance-policies/*.json
  try {
    if (fs.existsSync(POLICY_DIR)) {
      const files = fs.readdirSync(POLICY_DIR).filter(f => f.endsWith('.json'));
      for (const file of files) {
        try {
          const filePath = path.join(POLICY_DIR, file);
          const content = fs.readFileSync(filePath, 'utf-8');
          const policies = JSON.parse(content);
          const policyList = Array.isArray(policies) ? policies : [policies];
          for (const p of policyList) {
            if (p.id && p.action && p.conditions) {
              policyStore.set(p.id, {
                ...p,
                enabled: p.enabled !== false,
                severity: p.severity || 'T3',
                surfaces: p.surfaces || [],
              });
            }
          }
          log.info(`[PolicyRegistry] Loaded ${policyList.length} policies from ${file}`);
        } catch (err: any) {
          log.error(`[PolicyRegistry] Failed to load ${file}: ${err.message}`);
        }
      }
    }
  } catch (err: any) {
    log.error(`[PolicyRegistry] Failed to scan policy directory: ${err.message}`);
  }

  initialized = true;
  log.info(`[PolicyRegistry] Registry initialized with ${policyStore.size} total policies`);
}

// ============================================================================
// CRUD OPERATIONS
// ============================================================================

