import { NOT_ADMIN_ERR_MSG, UNAUTHED_ERR_MSG } from '@shared/const';
import { initTRPC, TRPCError } from "@trpc/server";
import superjson from "superjson";
import type { TrpcContext } from "./context";
import { createGovernanceMutationMiddleware } from "../governance/trpc-governance-middleware";

const t = initTRPC.context<TrpcContext>().create({
  transformer: superjson,
});

export const router = t.router;
export const mergeRouters = t.mergeRouters;
export const createCallerFactory = t.createCallerFactory;
export { t };

// ============================================================================
// GOVERNANCE MIDDLEWARE — Applied to ALL procedures
// ============================================================================
// This ensures every tRPC mutation passes through governance tracking.
// Content-generation mutations get 'enforced' level, others get 'monitored'.
// Combined with invokeLLM's truth injection + during-creation checks,
// this achieves architectural completeness: nothing generates content
// without Gravito knowing.

const governanceMutationMiddleware = createGovernanceMutationMiddleware(t);

// ============================================================================
// PROCEDURE DEFINITIONS
// ============================================================================

const requireUser = t.middleware(async opts => {
  const { ctx, next } = opts;

  if (!ctx.user) {
    throw new TRPCError({ code: "UNAUTHORIZED", message: UNAUTHED_ERR_MSG });
  }

  return next({
    ctx: {
      ...ctx,
      user: ctx.user,
    },
  });
});

// Public procedure — governance middleware tracks all mutations
export const publicProcedure = t.procedure.use(governanceMutationMiddleware);

// Protected procedure — requires auth + governance tracking
export const protectedProcedure = t.procedure.use(requireUser).use(governanceMutationMiddleware);

// Admin procedure — auth/authz gates fire before governance tracking to keep audit logs semantically consistent
export const adminProcedure = t.procedure.use(requireUser).use(
  t.middleware(async opts => {
    const { ctx, next } = opts;

    if (!ctx.user || ctx.user.role !== 'admin') {
      throw new TRPCError({ code: "FORBIDDEN", message: NOT_ADMIN_ERR_MSG });
    }

    return next({
      ctx: {
        ...ctx,
        user: ctx.user,
      },
    });
  }),
).use(governanceMutationMiddleware);

