  // ========================================================================
  // AUTO-FIX EXECUTION (Magic Moment)
  // ========================================================================

  /**
   * Execute an auto-fix for a specific fix-pack recommendation.
   * Maps fix-pack alert types to executeFixLayer domain filters.
   * This is the "click → score goes up" magic moment.
   *
   * The mapping between fix-pack alert types and fix-execution-layer domains:
   *   data_freshness      → 'freshness'
   *   typography_drift     → 'typography'
   *   accessibility_violation → 'accessibility'
   *   brand_voice_drift    → 'voice'
   */
  /**
   * Preview what an auto-fix would change before applying.
   * Returns exact code diffs grouped by file — the trust multiplier.
   */
  previewAutoFix: publicProcedure
    .input(z.object({
      alertType: z.enum([
        'data_freshness',
        'typography_drift',
        'accessibility_violation',
        'brand_voice_drift',
        'governance_dropout',
      ]),
    }))
    .query(async ({ input }) => {
      const alertToDomain: Record<string, string[]> = {
        data_freshness: ['freshness'],
        typography_drift: ['typography'],
        accessibility_violation: ['accessibility'],
        brand_voice_drift: ['voice'],
        governance_dropout: [],
      };

      const domains = alertToDomain[input.alertType];
      if (!domains || domains.length === 0) {
        return {
          available: false,
          error: `No auto-fix strategy available for: ${input.alertType}`,
          totalFixes: 0,
          totalFiles: 0,
          files: [],
          domains: [],
        };
      }

      try {
        // Run in dry-run mode — no files are modified
        const result = await executeFixLayer('dry-run', domains);

        // Group fixes by file for the diff view
        const fileMap = new Map<string, Array<{
          id: string;
          domain: string;
          violationType: string;
          lineNumber: number;
          description: string;
          before: string;
          after: string;
          confidence: number;
        }>>();

        for (const fix of result.fixes) {
          if (!fileMap.has(fix.file)) {
            fileMap.set(fix.file, []);
          }
          fileMap.get(fix.file)!.push({
            id: fix.id,
            domain: fix.domain,
            violationType: fix.violationType,
            lineNumber: fix.lineNumber,
            description: fix.description,
            before: fix.before,
            after: fix.after,
            confidence: fix.confidence,
          });
        }

        // Sort fixes within each file by line number
        const files = Array.from(fileMap.entries()).map(([filePath, fixes]) => ({
          filePath,
          fixCount: fixes.length,
          fixes: fixes.sort((a, b) => a.lineNumber - b.lineNumber),
        }));

        // Sort files by fix count descending
        files.sort((a, b) => b.fixCount - a.fixCount);

        return {
          available: true,
          error: null,
          totalFixes: result.totalFixesAttempted,
          totalFiles: files.length,
          files,
          domains: domains,
        };
      } catch (err) {
        return {
          available: false,
          error: `Preview failed: ${(err as Error).message}`,
          totalFixes: 0,
          totalFiles: 0,
          files: [],
          domains: [],
        };
      }
    }),

  executeAutoFix: publicProcedure
    .input(z.object({
      fixId: z.string(),
      alertType: z.enum([
        'data_freshness',
        'typography_drift',
        'accessibility_violation',
        'brand_voice_drift',
        'governance_dropout',
      ]),
      selectedFixIds: z.array(z.string()).optional(),
    }))
    .mutation(async ({ input }) => {
      // Map fix-pack alert types to fix-execution-layer domain names
      const alertToDomain: Record<string, string[]> = {
        data_freshness: ['freshness'],
        typography_drift: ['typography'],
        accessibility_violation: ['accessibility'],
        brand_voice_drift: ['voice'],
        governance_dropout: [], // Not auto-fixable via file changes
      };

      const domains = alertToDomain[input.alertType];
      if (!domains || domains.length === 0) {
        return {
          success: false,
          error: `No auto-fix strategy available for alert type: ${input.alertType}`,
          result: null,
          scoreBefore: null,
          scoreAfter: null,
          scoreDelta: null,
        };
      }

      try {
        // Get score before fix
        const scoreBefore = (await calculateContentIntegrityScore()).overallScore;

        // Execute the fix in live mode, filtered to the relevant domain
        // If selectedFixIds provided, run dry-run first to get all fixes, then apply only selected ones
        const result = await executeFixLayer('live', domains, input.selectedFixIds);

        // Get score after fix (fresh calculation)
        const scoreAfter = (await calculateContentIntegrityScore()).overallScore;
        const scoreDelta = scoreAfter - scoreBefore;

        governanceLog.info(`[AutoFix] Executed for ${input.alertType} (domains: ${domains.join(',')}): ${result.totalFixesApplied} fixes applied, score ${scoreBefore} → ${scoreAfter} (${scoreDelta >= 0 ? '+' : ''}${scoreDelta})`);

        return {
          success: result.totalFixesApplied > 0,
          error: result.totalFixesFailed > 0
            ? `${result.totalFixesFailed} fixes failed during execution`
            : null,
          result: {
            runId: result.runId,
            totalFixesApplied: result.totalFixesApplied,
            totalFixesFailed: result.totalFixesFailed,
            fixesByDomain: result.fixesByDomain,
            durationMs: result.durationMs,
            rollbackAvailable: result.rollbackAvailable,
          },
          scoreBefore,
          scoreAfter,
          scoreDelta,
        };
      } catch (err) {
        governanceLog.error(`[AutoFix] Execution failed for ${input.alertType}:`, err);
        return {
          success: false,
          error: `Auto-fix execution failed: ${(err as Error).message}`,
          result: null,
          scoreBefore: null,
          scoreAfter: null,
          scoreDelta: null,
        };
      }
    }),

