  // Enhanced preview that includes threshold-based selection
  previewAutoFixWithThresholds: publicProcedure
    .input(z.object({
      alertType: z.enum([
        'data_freshness',
        'typography_drift',
        'accessibility_violation',
        'brand_voice_drift',
        'governance_dropout',
      ]),
    }))
    .query(async ({ input }) => {
      const alertToDomain: Record<string, string[]> = {
        data_freshness: ['freshness'],
        typography_drift: ['typography'],
        accessibility_violation: ['accessibility'],
        brand_voice_drift: ['voice'],
        governance_dropout: [],
      };

      const domains = alertToDomain[input.alertType];
      if (!domains || domains.length === 0) {
        return { available: false, files: [], totalFixes: 0, totalFiles: 0, thresholds: await getConfidenceThresholds(), preSelectedIds: [] };
      }

      try {
        const result = await executeFixLayer('dry-run', domains);
        const thresholds = await getConfidenceThresholds();

        // Build file groups with threshold-based pre-selection
        const preSelectedIds: string[] = [];
        const fileMap = new Map<string, Array<{
          id: string;
          domain: string;
          violationType: string;
          lineNumber: number;
          description: string;
          before: string;
          after: string;
          confidence: number;
          meetsThreshold: boolean;
          confidenceTier: 'high' | 'medium' | 'manual';
        }>>();

        for (const fix of result.fixes) {
          const domainThreshold = getEffectiveThreshold(thresholds, fix.domain);
          const meetsThreshold = fix.confidence >= domainThreshold;
          const confidenceTier: 'high' | 'medium' | 'manual' = 
            fix.confidence >= 90 ? 'high' : 
            fix.confidence >= 70 ? 'medium' : 'manual';

          if (meetsThreshold && fix.before !== fix.after) {
            preSelectedIds.push(fix.id);
          }

          const existing = fileMap.get(fix.file) || [];
          existing.push({
            id: fix.id,
            domain: fix.domain,
            violationType: fix.violationType,
            lineNumber: fix.lineNumber,
            description: fix.description,
            before: fix.before,
            after: fix.after,
            confidence: fix.confidence,
            meetsThreshold,
            confidenceTier,
          });
          fileMap.set(fix.file, existing);
        }

        const files = Array.from(fileMap.entries()).map(([filePath, fixes]) => ({
          filePath,
          fixes,
        }));

        const totalFixes = files.reduce((sum, f) => sum + f.fixes.length, 0);

        return {
          available: totalFixes > 0,
          files,
          totalFixes,
          totalFiles: files.length,
          thresholds,
          preSelectedIds,
        };
      } catch (err) {
        governanceLog.error(`[PreviewWithThresholds] Failed for ${input.alertType}:`, err);
        return { available: false, files: [], totalFixes: 0, totalFiles: 0, thresholds: await getConfidenceThresholds(), preSelectedIds: [] };
      }
    }),

