      days: z.number().min(1).max(90).default(30),
    }).optional())
    .query(async ({ ctx, input }) => {
      const userId = ctx.user?.id ?? null;
      if (!userId) {
        return {
          plan: { key: 'builder' as const, name: 'Builder', price: null as number | null, period: 'month' as const },
          scanUsage: { used: 0, limit: 75000, remaining: 75000, percentUsed: 0, isUnlimited: false, upgradeRequired: false },
          featureGates: getFeatureGates('builder'),
          dailyUsage: [] as Array<{ date: string; scans: number }>,
          subscription: null as { status: string; plan: string; cancelAtPeriodEnd: boolean | null } | null,
          upgradeNudge: null as { level: 'info' | 'warning' | 'critical'; message: string; suggestedPlan: string } | null,
          periodStart: new Date().toISOString(),
          periodEnd: new Date().toISOString(),
        };
      }
      const days = input?.days || 30;
      const usage = await getScanUsageInfo(userId);
      const gates = getFeatureGates(usage.planKey);
      const dailyUsage = await getUsageByUserId(userId, days);
      const subscription = await getSubscriptionByUserId(userId);

      const planDisplayNames: Record<string, string> = {
        builder: 'Builder', startup: 'Startup', company: 'Company', regulated_enterprise: 'Regulated Enterprise', internal: 'Internal',
      };
      const planPrices: Record<string, number | null> = {
        builder: 750, startup: 3500, company: 12500, regulated_enterprise: 50000, internal: null,
      };

      let upgradeNudge: { level: 'info' | 'warning' | 'critical'; message: string; suggestedPlan: string } | null = null;
      if (!usage.isUnlimited) {
        if (usage.percentUsed >= 100) {
          upgradeNudge = {
            level: 'critical',
            message: `You've used all ${usage.scansLimit} scans this month. Upgrade to continue scanning.`,
            suggestedPlan: usage.planKey === 'builder' ? 'startup' : usage.planKey === 'startup' ? 'company' : 'regulated_enterprise',
          };
        } else if (usage.percentUsed >= 80) {
          upgradeNudge = {
            level: 'warning',
            message: `You've used ${usage.scansUsed} of ${usage.scansLimit} governed checks (${usage.percentUsed}%). Overage will be billed.`,
            suggestedPlan: usage.planKey === 'builder' ? 'startup' : usage.planKey === 'startup' ? 'company' : 'regulated_enterprise',
          };
        } else if (usage.percentUsed >= 50) {
          upgradeNudge = {
            level: 'info',
            message: `You've used ${usage.scansUsed} of ${usage.scansLimit} governed checks this month.`,
            suggestedPlan: usage.planKey === 'builder' ? 'startup' : usage.planKey === 'startup' ? 'company' : 'regulated_enterprise',
          };
        }
      }

      const now = new Date();
      const periodStart = subscription?.currentPeriodStart || new Date(now.getFullYear(), now.getMonth(), 1);
      const periodEnd = subscription?.currentPeriodEnd || new Date(now.getFullYear(), now.getMonth() + 1, 0);

      const dailyAggregated = (dailyUsage || []).reduce((acc: Record<string, number>, row: any) => {
        const dateKey = new Date(row.date).toISOString().split('T')[0];
        acc[dateKey] = (acc[dateKey] || 0) + (row.callCount || 0);
        return acc;
      }, {} as Record<string, number>);

      const chartData: Array<{ date: string; scans: number }> = [];
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - days);
      for (let d = new Date(startDate); d <= now; d.setDate(d.getDate() + 1)) {
        const dateKey = d.toISOString().split('T')[0];
        chartData.push({ date: dateKey, scans: dailyAggregated[dateKey] || 0 });
      }

      return {
        plan: {
          key: usage.planKey,
          name: planDisplayNames[usage.planKey] || 'Explorer',
          price: planPrices[usage.planKey],
          period: 'month' as const,
        },
        scanUsage: {
          used: usage.scansUsed,
          limit: usage.scansLimit,
          remaining: usage.scansRemaining,
          percentUsed: usage.percentUsed,
          isUnlimited: usage.isUnlimited,
          upgradeRequired: usage.upgradeRequired,
        },
        featureGates: gates,
        dailyUsage: chartData,
        subscription: subscription ? {
          status: subscription.status,
          plan: subscription.plan,
          cancelAtPeriodEnd: subscription.cancelAtPeriodEnd,
        } : null,
        upgradeNudge,
        periodStart: periodStart instanceof Date ? periodStart.toISOString() : String(periodStart),
        periodEnd: periodEnd instanceof Date ? periodEnd.toISOString() : String(periodEnd),
      };
    }),

