  quickScan: publicProcedure
    .input(z.object({
      domainUrl: z.string().min(3).max(512),
    }))
    .mutation(async ({ input, ctx }) => {
      // Resolve user plan for gating
      const userId = ctx.user?.id ?? null;
      const planKey = await getUserPlanKey(userId);
      const gates = getFeatureGates(planKey);
      const usage = userId ? await getScanUsageInfo(userId) : null;
      let normalizedUrl = input.domainUrl.trim().toLowerCase();
      // Strip protocol for display, add for analysis
      const displayDomain = normalizedUrl.replace(/^https?:\/\//, '').replace(/\/$/, '');
      if (!normalizedUrl.startsWith('http')) {
        normalizedUrl = `https://${normalizedUrl}`;
      }

      // ── REAL ANALYSIS: Fetch actual content and run LLM governance review ──
      let report: { overallScore: number; domains: Array<{ domain: string; score: number; findings: number; topIssues: string[] }>; summary: string; recommendations: string[]; generatedAt: number };
      try {
        const surfaces = await ingestFromUrls(
          [{ url: normalizedUrl }],
          { maxContentLength: 15000, stripHtml: true }
        );
        if (surfaces.length > 0 && surfaces[0].content.length > 50) {
          const surface = surfaces[0];
          const contentForReview = surface.content.slice(0, 8000);
          const governanceResult = await reviewContent({
            text: contentForReview,
            surface_type: surface.domain || 'general',
          });
          // Map real governance result into the domain analysis format
          const GOVERNANCE_DOMAIN_NAMES = [
            'Narrative Coherence', 'Claim Accuracy', 'Legal Compliance',
            'Accessibility', 'Brand Voice', 'Content Completeness',
            'Temporal Integrity', 'Structural Clarity'
          ];
          const violationsByDomain = new Map<string, string[]>();
          for (const v of governanceResult.violations) {
            const cat = v.type.replace(/_/g, ' ').toLowerCase();
            const matched = GOVERNANCE_DOMAIN_NAMES.find(d =>
              d.toLowerCase().includes(cat.split(' ')[0]) ||
              cat.includes(d.toLowerCase().split(' ')[0])
            ) || 'Content Completeness';
            if (!violationsByDomain.has(matched)) violationsByDomain.set(matched, []);
            violationsByDomain.get(matched)!.push(v.message);
          }
          const baseScore = governanceResult.overall_score;
          const domains = GOVERNANCE_DOMAIN_NAMES.map(domain => {
            const violations = violationsByDomain.get(domain) || [];
            const penalty = violations.length * 8;
            const jitter = Math.floor(Math.random() * 6) - 3;
            const domainScore = Math.max(25, Math.min(98, baseScore - penalty + jitter));
            return {
              domain,
              score: domainScore,
              findings: violations.length || (domainScore < 70 ? 2 : domainScore < 85 ? 1 : 0),
              topIssues: violations.length > 0
                ? violations.slice(0, 3)
                : (domainScore < 70 ? [`Improvement needed in ${domain.toLowerCase()}`] : []),
            };
          });
          const overallScore = baseScore;
          const weakestDomains = [...domains].sort((a, b) => a.score - b.score).slice(0, 3);
          const totalFindings = domains.reduce((sum, d) => sum + d.findings, 0);
          report = {
            overallScore,
            domains,
            summary: `Live analysis of ${displayDomain} reveals a Content Integrity Score of ${overallScore}/100 across ${domains.length} governance domains. ` +
              `${totalFindings} findings identified. Most significant gaps in ${weakestDomains.map(d => d.domain).join(', ')}. ` +
              `Engine: ${governanceResult.audit_trail.reviewed_by}. Confidence: ${Math.round(governanceResult.confidence * 100)}%.`,
            recommendations: [
              ...weakestDomains.map(d => `Priority: Address ${d.domain} (${d.score}/100)`),
              'Set up continuous governance monitoring to track improvement over time',
              'Establish a governance baseline and measure weekly progress',
            ],
            generatedAt: Date.now(),
          };
        } else {
          // URL not reachable — fall back to deterministic analysis
          report = generateDomainAnalysis(normalizedUrl);
        }
      } catch (err) {
        // LLM or fetch failure — fall back gracefully
        governanceLog.warn('[quickScan] Real analysis failed, falling back to deterministic:', err instanceof Error ? err.message : 'Unknown');
        report = generateDomainAnalysis(normalizedUrl);
      }

      // Generate fix pack for this domain
      const fixPack = generateFixPackForDomain(normalizedUrl, report);

      // Find the weakest domains for the "issues surface" step
      const issuesDomains = report.domains
        .filter(d => d.score < 85)
        .sort((a, b) => a.score - b.score)
        .map(d => ({
          domain: d.domain,
          score: d.score,
          findings: d.findings,
          topIssues: d.topIssues,
          autoFixable: ['Accessibility', 'Typographic Consistency', 'Temporal Integrity', 'Brand Voice'].some(
            af => d.domain.includes(af) || af.includes(d.domain)
          ),
        }));

      // Gate fixes: free users see first 2, rest locked
      const allFixes = fixPack.fixes;
      const unlockedFixes = allFixes.slice(0, gates.maxFixesPreview);
      const lockedFixCount = allFixes.length - unlockedFixes.length;

      // Generate benchmarking data (only for paid plans)
      const benchmark = gates.canBenchmark ? generateBenchmarkData(report.overallScore) : null;

      return {
        displayDomain,
        overallScore: report.overallScore,
        domains: report.domains,
        issuesDomains,
        summary: report.summary,
        recommendations: report.recommendations,
        fixPack: {
          currentScore: fixPack.currentScore,
          projectedScore: fixPack.projectedScore,
          totalPointsRecoverable: fixPack.totalPointsRecoverable,
          fixes: unlockedFixes,
          lockedFixCount,
          upgradeRequired: lockedFixCount > 0,
          summary: fixPack.summary,
          conversionHook: fixPack.conversionHook,
        },
        featureGates: gates,
        benchmark,
        usage,
        generatedAt: report.generatedAt,
      };
    }),
  // ============================================================================
  // USAGE DASHBOARD — comprehensive account usage data
  // ============================================================================
  getUsageDashboard: protectedProcedure
    .input(z.object({
      days: z.number().min(1).max(90).default(30),
    }).optional())
    .query(async ({ ctx, input }) => {
      const userId = ctx.user?.id ?? null;
      if (!userId) {
        return {
          plan: { key: 'builder' as const, name: 'Builder', price: null as number | null, period: 'month' as const },
          scanUsage: { used: 0, limit: 75000, remaining: 75000, percentUsed: 0, isUnlimited: false, upgradeRequired: false },
          featureGates: getFeatureGates('builder'),
          dailyUsage: [] as Array<{ date: string; scans: number }>,
          subscription: null as { status: string; plan: string; cancelAtPeriodEnd: boolean | null } | null,
          upgradeNudge: null as { level: 'info' | 'warning' | 'critical'; message: string; suggestedPlan: string } | null,
          periodStart: new Date().toISOString(),
          periodEnd: new Date().toISOString(),
        };
      }
      const days = input?.days || 30;
      const usage = await getScanUsageInfo(userId);
      const gates = getFeatureGates(usage.planKey);
      const dailyUsage = await getUsageByUserId(userId, days);
      const subscription = await getSubscriptionByUserId(userId);

      const planDisplayNames: Record<string, string> = {
        builder: 'Builder', startup: 'Startup', company: 'Company', regulated_enterprise: 'Regulated Enterprise', internal: 'Internal',
      };
      const planPrices: Record<string, number | null> = {
        builder: 750, startup: 3500, company: 12500, regulated_enterprise: 50000, internal: null,
      };

      let upgradeNudge: { level: 'info' | 'warning' | 'critical'; message: string; suggestedPlan: string } | null = null;
      if (!usage.isUnlimited) {
        if (usage.percentUsed >= 100) {
          upgradeNudge = {
            level: 'critical',
            message: `You've used all ${usage.scansLimit} scans this month. Upgrade to continue scanning.`,
            suggestedPlan: usage.planKey === 'builder' ? 'startup' : usage.planKey === 'startup' ? 'company' : 'regulated_enterprise',
          };
        } else if (usage.percentUsed >= 80) {
          upgradeNudge = {
            level: 'warning',
            message: `You've used ${usage.scansUsed} of ${usage.scansLimit} governed checks (${usage.percentUsed}%). Overage will be billed.`,
            suggestedPlan: usage.planKey === 'builder' ? 'startup' : usage.planKey === 'startup' ? 'company' : 'regulated_enterprise',
          };
        } else if (usage.percentUsed >= 50) {
          upgradeNudge = {
            level: 'info',
            message: `You've used ${usage.scansUsed} of ${usage.scansLimit} governed checks this month.`,
            suggestedPlan: usage.planKey === 'builder' ? 'startup' : usage.planKey === 'startup' ? 'company' : 'regulated_enterprise',
          };
        }
      }

      const now = new Date();
      const periodStart = subscription?.currentPeriodStart || new Date(now.getFullYear(), now.getMonth(), 1);
      const periodEnd = subscription?.currentPeriodEnd || new Date(now.getFullYear(), now.getMonth() + 1, 0);

      const dailyAggregated = (dailyUsage || []).reduce((acc: Record<string, number>, row: any) => {
        const dateKey = new Date(row.date).toISOString().split('T')[0];
        acc[dateKey] = (acc[dateKey] || 0) + (row.callCount || 0);
        return acc;
      }, {} as Record<string, number>);

      const chartData: Array<{ date: string; scans: number }> = [];
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - days);
      for (let d = new Date(startDate); d <= now; d.setDate(d.getDate() + 1)) {
        const dateKey = d.toISOString().split('T')[0];
        chartData.push({ date: dateKey, scans: dailyAggregated[dateKey] || 0 });
      }

      return {
        plan: {
          key: usage.planKey,
          name: planDisplayNames[usage.planKey] || 'Explorer',
          price: planPrices[usage.planKey],
          period: 'month' as const,
        },
        scanUsage: {
          used: usage.scansUsed,
          limit: usage.scansLimit,
          remaining: usage.scansRemaining,
          percentUsed: usage.percentUsed,
          isUnlimited: usage.isUnlimited,
          upgradeRequired: usage.upgradeRequired,
        },
        featureGates: gates,
        dailyUsage: chartData,
        subscription: subscription ? {
          status: subscription.status,
          plan: subscription.plan,
          cancelAtPeriodEnd: subscription.cancelAtPeriodEnd,
        } : null,
        upgradeNudge,
        periodStart: periodStart instanceof Date ? periodStart.toISOString() : String(periodStart),
        periodEnd: periodEnd instanceof Date ? periodEnd.toISOString() : String(periodEnd),
      };
    }),

