tool_use_result.originalFile:
/**
 * Control Tower Router - Live Data Endpoints
 * 
 * Provides real-time governance data for the Control Tower dashboard:
 * - Live decision feed (approvals, blocks, patches)
 * - Chain of custody visualization
 * - Surface metrics breakdown
 * - Outcome attribution display
 * - Audit trail explorer
 */

import { z } from 'zod';
import { TRPCError } from '@trpc/server';
import { router, adminProcedure } from '../_core/trpc';
import { governedProtectedProcedure as protectedProcedure, governedPublicProcedure as publicProcedure } from './trpc-enforcement';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import {
  calculateAllDriftSeverities,
  calculateAllCorrectionConfidences,
  calculateDriftSeverity,
  calculateCorrectionConfidence,
  generateGovernanceHealthReport,
  getRecentDriftSnapshots,
  getBaselineHistory,
} from './governance-persistence';
import { getWatchdogReport } from './watchdog';
import { forceTypographyScan, runStaticTypographyScan, TYPOGRAPHY_DESIGN_TOKENS } from './typography-governance';
import { forceAccessibilityScan, runStaticAccessibilityScan } from './accessibility-governance';
import { forceFreshnessScan, runStaticFreshnessScan } from './data-freshness-governance';
import { forceCompletenessScan, runStaticCompletenessScan } from './content-completeness-governance';
import { forceBrandVoiceScan, runStaticBrandVoiceScan, BRAND_VOICE_PROFILE } from './brand-voice-governance';
import { calculateContentIntegrityScore, getDomainWeights, DOMAIN_WEIGHTS } from './content-integrity-score';
import { calculateContentIntelligence, getContentIntelligenceSummary } from './content-intelligence';
import { getDigestibilityTrend } from './digestibility-trend';
import { getScoreTrend, getScoreHistory, recordIntegrityScoreSnapshot } from './integrity-score-trend';
import { runAutoRemediation, getRemediationHistory, getLatestRemediationResult } from './auto-remediation';
import { executeFixLayer, getFixPreview, rollbackFixRun, getRollbackStatus, hasRollback, getAvailableRollbacks } from './fix-execution-layer';
import { dispatchRemediationNotification, getNotificationConfig } from './remediation-notifications';
import { submitReportRequest, getReportByRequestId, getRecentReportRequests, generateDomainAnalysis } from './report-generator';
import { reviewContent } from './demo-review-engine';
import { ingestFromUrls } from './content-surface-ingester';
import { getChangelogEntries, getChangelogStats, seedChangelogFromHistory } from './changelog-service';
import { generateFixPack, generateFixPackForDomain } from './fix-pack-engine';
import { getConfidenceThresholds, updateConfidenceThresholds, getEffectiveThreshold, type ConfidenceThresholds, getUsageByUserId, getSubscriptionByUserId } from '../db';
import { getUserPlanKey, getScanUsageInfo, getFeatureGates, generateBenchmarkData, getUpgradeSuggestion } from './scan-usage';
import { checkUsageAlerts, calculateProjectedExhaustion, getUserAlertHistory } from './usage-alerts';
import { getDigestPreferences, upsertDigestPreferences, aggregateDigestData, formatDigestContent, sendDigestForUser, getUsageDigestSchedulerStatus } from './usage-digest';
import {
  getActivePolicies as pceGetActivePolicies,
  getRegistryStats as pceGetRegistryStats,
  upsertPolicy as pceUpsertPolicy,
  togglePolicy as pceTogglePolicy,
  removePolicy as pceRemovePolicy,
  resetToDefaults as pceResetToDefaults,
} from './policy/policyRegistry';
import {
  getPCEHistory,
  getComplianceTrend,
  getViolationSummary,
} from './policy/policyEngine';
import {
  getAutoTunerConfig,
  updateAutoTunerConfig,
  getTuningHistory,
  getLatestTuning,
  runAutoTuner as pceRunAutoTuner,
} from './policy/autoTuner';
import type { PolicyDefinition, PolicyCondition, PolicyAction, PolicySeverity } from './policy/policySchema';
import {
  getUserOrganization,
  createOrganization,
  getTeamMembers,
  updateMemberRole,
  removeMember,
  sendInvitation,
  getOrgInvitations,
  revokeInvitation,
  acceptInvitation,
  getSeatAllocation,
  getTeamUsageRollup,
  isTeamAdmin,
  canManageTeam,
  getSeatLimit,
} from './team-management';
import { sendInvitationEmail } from '../services/team-invitation-email';
import { runWeeklyDigest, gatherDigestData, getDigestSchedulerStatus } from './weekly-resolution-digest';
import { getResolverStats, getRecentResolutions, getResolutionDbStats } from './claude-auto-resolver';
import { governanceLog } from '../_core/logger';
import { shapeCast } from '../../shared/type-bridge';

// Types for Control Tower data
interface GovernanceDecision {
  id: string;
  timestamp: string;
  surface: string;
  action: string;
  decision: 'PASS' | 'BLOCK' | 'PATCH_REQUIRED';
  status: 'RELEASED' | 'BLOCKED' | 'PATCHED_AND_RELEASED';
  proofBlockId: string;
  scores: {
    accuracy: number;
    compliance: number;
    tone: number;
    completeness: number;
  };
  policyVersion: string;
  model: string;
  outcomeMetric?: string;
}

interface ChainOfCustody {
  id: string;
  proofBlockId: string;
  steps: {
    step: number;
    action: string;
    timestamp: string;
    actor: string;
    result: string;
  }[];
}

interface SurfaceMetrics {
  surface: string;
  totalDecisions: number;
  passRate: number;
  blockRate: number;
  patchRate: number;
  avgScore: number;
  outcomeImprovement: number;
}

interface OutcomeAttribution {
  id: string;
  surface: string;
  metric: string;
  baseline: number;
  actual: number;
  improvement: number;
  confidence: number;
  proofBlockIds: string[];
}

// In-memory store for demo (in production, this would be a database)
let governanceDecisions: GovernanceDecision[] = [];
let chainOfCustodyRecords: ChainOfCustody[] = [];

// Load demo results if available
function loadDemoResults(): void {
  const demoResultsPath = join(process.cwd(), 'docs', 'DEMO_RESULTS_LIVE.json');
  if (existsSync(demoResultsPath)) {
    try {
      const data = JSON.parse(readFileSync(demoResultsPath, 'utf-8'));
      governanceDecisions = data.map((d: any, index: number) => ({
        id: `decision_${Date.now()}_${index}`,
        timestamp: d.timestamp,
        surface: d.surface,
        action: d.input.substring(0, 50) + '...',
        decision: d.gravitoDecision,
        status: d.finalStatus,
        proofBlockId: d.proofBlock.id,
        scores: d.proofBlock.reviewer_scores,
        policyVersion: d.proofBlock.policy_version,
        model: d.proofBlock.provenance.model,
        outcomeMetric: d.outcomeMetric,
      }));

      // Generate chain of custody for each decision
      chainOfCustodyRecords = governanceDecisions.map((d, index) => ({
        id: `coc_${Date.now()}_${index}`,
        proofBlockId: d.proofBlockId,
        steps: [
          { step: 1, action: 'Request received', timestamp: d.timestamp, actor: 'User', result: 'Queued' },
          { step: 2, action: 'Surface detected', timestamp: d.timestamp, actor: 'Gravito', result: d.surface },
          { step: 3, action: 'Policy loaded', timestamp: d.timestamp, actor: 'Gravito', result: d.policyVersion },
          { step: 4, action: 'Content generated', timestamp: d.timestamp, actor: d.model, result: 'Generated' },
          { step: 5, action: 'Governance audit', timestamp: d.timestamp, actor: 'Gravito', result: d.decision },
          { step: 6, action: 'Final decision', timestamp: d.timestamp, actor: 'Gravito', result: d.status },
        ],
      }));
    } catch (error) {
      governanceLog.error('Failed to load demo results:', error);
    }
  }
}

// Initialize with demo data
loadDemoResults();

export const controlTowerRouter = router({
  /**
   * Get live decision feed with pagination
   */
  getDecisionFeed: protectedProcedure
    .input(z.object({
      limit: z.number().min(1).max(100).default(20),
      offset: z.number().min(0).default(0),
      surface: z.string().optional(),
      decision: z.enum(['PASS', 'BLOCK', 'PATCH_REQUIRED']).optional(),
    }))
    .query(async ({ input }) => {
      // Reload demo results to get latest data
      loadDemoResults();

      let filtered = [...governanceDecisions];

      if (input.surface) {
        filtered = filtered.filter(d => d.surface.toLowerCase().includes(input.surface!.toLowerCase()));
      }

      if (input.decision) {
        filtered = filtered.filter(d => d.decision === input.decision);
      }

      // Sort by timestamp descending
      filtered.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

      return {
        decisions: filtered.slice(input.offset, input.offset + input.limit),
        total: filtered.length,
        hasMore: input.offset + input.limit < filtered.length,
      };
    }),

  /**
   * Get chain of custody for a specific proof block
   */
  getChainOfCustody: protectedProcedure
    .input(z.object({
      proofBlockId: z.string(),
    }))
    .query(async ({ input }) => {
      const record = chainOfCustodyRecords.find(c => c.proofBlockId === input.proofBlockId);
      return record || null;
    }),

  /**
   * Get surface metrics breakdown
   */
  getSurfaceMetrics: protectedProcedure
    .query(async () => {
      loadDemoResults();

      const surfaces = ['Medical Email', 'Financial Advice', 'Legal Review', 'Sales Email', 'Support Escalation'];

      return surfaces.map(surface => {
        const surfaceDecisions = governanceDecisions.filter(d => d.surface === surface);
        const total = surfaceDecisions.length || 1;

        const passCount = surfaceDecisions.filter(d => d.decision === 'PASS').length;
        const blockCount = surfaceDecisions.filter(d => d.decision === 'BLOCK').length;
        const patchCount = surfaceDecisions.filter(d => d.decision === 'PATCH_REQUIRED').length;

        const avgScore = surfaceDecisions.reduce((sum, d) => {
          const scores = d.scores;
          return sum + (scores.accuracy + scores.compliance + scores.tone + scores.completeness) / 4;
        }, 0) / total;

        // Parse outcome improvement from metric string
        let outcomeImprovement = 0;
        if (surfaceDecisions[0]?.outcomeMetric) {
          const match = surfaceDecisions[0].outcomeMetric.match(/(\d+\.?\d*)%.*baseline.*?(\d+\.?\d*)%/);
          if (match) {
            outcomeImprovement = parseFloat(match[1]) - parseFloat(match[2]);
          }
        }

        return {
          surface,
          totalDecisions: total,
          passRate: (passCount / total) * 100,
          blockRate: (blockCount / total) * 100,
          patchRate: (patchCount / total) * 100,
          avgScore: avgScore * 100,
          outcomeImprovement,
        };
      });
    }),

  /**
   * Get outcome attribution data
   */
  getOutcomeAttribution: protectedProcedure
    .query(async () => {
      loadDemoResults();

      const attributions: OutcomeAttribution[] = [
        {
          id: 'attr_medical',
          surface: 'Medical Email',
          metric: 'Appointment Scheduled Rate',
          baseline: 72,
          actual: 89,
          improvement: 17,
          confidence: 85,
          proofBlockIds: governanceDecisions.filter(d => d.surface === 'Medical Email').map(d => d.proofBlockId),
        },
        {
          id: 'attr_financial',
          surface: 'Financial Advice',
          metric: 'Client Conversion Rate',
          baseline: 34,
          actual: 52,
          improvement: 18,
          confidence: 78,
          proofBlockIds: governanceDecisions.filter(d => d.surface === 'Financial Advice').map(d => d.proofBlockId),
        },
        {
          id: 'attr_legal',
          surface: 'Legal Review',
          metric: 'Issue Detection Rate',
          baseline: 67,
          actual: 91,
          improvement: 24,
          confidence: 82,
          proofBlockIds: governanceDecisions.filter(d => d.surface === 'Legal Review').map(d => d.proofBlockId),
        },
        {
          id: 'attr_sales',
          surface: 'Sales Email',
          metric: 'Reply Rate',
          baseline: 18,
          actual: 31,
          improvement: 13,
          confidence: 76,
          proofBlockIds: governanceDecisions.filter(d => d.surface === 'Sales Email').map(d => d.proofBlockId),
        },
        {
          id: 'attr_support',
          surface: 'Support Escalation',
          metric: 'CSAT Score',
          baseline: 3.2,
          actual: 4.5,
          improvement: 1.3,
          confidence: 88,
          proofBlockIds: governanceDecisions.filter(d => d.surface === 'Support Escalation').map(d => d.proofBlockId),
        },
      ];

      return attributions;
    }),

  /**
   * Get audit trail with filters
   */
  getAuditTrail: protectedProcedure
    .input(z.object({
      startDate: z.string().optional(),
      endDate: z.string().optional(),
      surface: z.string().optional(),
      decision: z.enum(['PASS', 'BLOCK', 'PATCH_REQUIRED']).optional(),
      limit: z.number().min(1).max(1000).default(100),
    }))
    .query(async ({ input }) => {
      loadDemoResults();

      let filtered = [...governanceDecisions];

      if (input.startDate) {
        const start = new Date(input.startDate);
        filtered = filtered.filter(d => new Date(d.timestamp) >= start);
      }

      if (input.endDate) {
        const end = new Date(input.endDate);
        filtered = filtered.filter(d => new Date(d.timestamp) <= end);
      }

      if (input.surface) {
        filtered = filtered.filter(d => d.surface.toLowerCase().includes(input.surface!.toLowerCase()));
      }

      if (input.decision) {
        filtered = filtered.filter(d => d.decision === input.decision);
      }

      return {
        entries: filtered.slice(0, input.limit).map(d => ({
          id: d.id,
          timestamp: d.timestamp,
          surface: d.surface,
          action: d.action,
          decision: d.decision,
          status: d.status,
          proofBlockId: d.proofBlockId,
          policyVersion: d.policyVersion,
          model: d.model,
          scores: d.scores,
        })),
        total: filtered.length,
      };
    }),

  /**
   * Get real-time stats summary
   */
  getStatsSummary: protectedProcedure
    .query(async () => {
      loadDemoResults();

      const total = governanceDecisions.length;
      const passed = governanceDecisions.filter(d => d.decision === 'PASS').length;
      const blocked = governanceDecisions.filter(d => d.decision === 'BLOCK').length;
      const patched = governanceDecisions.filter(d => d.decision === 'PATCH_REQUIRED').length;

      const avgScore = governanceDecisions.reduce((sum, d) => {
        const scores = d.scores;
        return sum + (scores.accuracy + scores.compliance + scores.tone + scores.completeness) / 4;
      }, 0) / (total || 1);

      const surfaceCounts = governanceDecisions.reduce((acc, d) => {
        acc[d.surface] = (acc[d.surface] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);

      return {
        totalDecisions: total,
        passRate: total ? (passed / total) * 100 : 0,
        blockRate: total ? (blocked / total) * 100 : 0,
        patchRate: total ? (patched / total) * 100 : 0,
        avgGovernanceScore: avgScore * 100,
        surfaceBreakdown: surfaceCounts,
        lastUpdated: new Date().toISOString(),
      };
    }),

  /**
   * Record a new governance decision (for live integration)
   */
  recordDecision: adminProcedure
    .input(z.object({
      surface: z.string(),
      action: z.string(),
      decision: z.enum(['PASS', 'BLOCK', 'PATCH_REQUIRED']),
      status: z.enum(['RELEASED', 'BLOCKED', 'PATCHED_AND_RELEASED']),
      scores: z.object({
        accuracy: z.number(),
        compliance: z.number(),
        tone: z.number(),
        completeness: z.number(),
      }),
      policyVersion: z.string(),
      model: z.string(),
      outcomeMetric: z.string().optional(),
    }))
    .mutation(async ({ input }) => {
      const id = `decision_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
      const proofBlockId = `proof_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;

      const decision: GovernanceDecision = {
        id,
        timestamp: new Date().toISOString(),
        surface: input.surface,
        action: input.action,
        decision: input.decision,
        status: input.status,
        proofBlockId,
        scores: input.scores,
        policyVersion: input.policyVersion,
        model: input.model,
        outcomeMetric: input.outcomeMetric,
      };

      governanceDecisions.unshift(decision);

      // Create chain of custody
      chainOfCustodyRecords.unshift({
        id: `coc_${Date.now()}`,
        proofBlockId,
        steps: [
          { step: 1, action: 'Request received', timestamp: decision.timestamp, actor: 'User', result: 'Queued' },
          { step: 2, action: 'Surface detected', timestamp: decision.timestamp, actor: 'Gravito', result: input.surface },
          { step: 3, action: 'Policy loaded', timestamp: decision.timestamp, actor: 'Gravito', result: input.policyVersion },
          { step: 4, action: 'Content generated', timestamp: decision.timestamp, actor: input.model, result: 'Generated' },
          { step: 5, action: 'Governance audit', timestamp: decision.timestamp, actor: 'Gravito', result: input.decision },
          { step: 6, action: 'Final decision', timestamp: decision.timestamp, actor: 'Gravito', result: input.status },
        ],
      });

      return { id, proofBlockId };
    }),

  // ============================================================================
  // DRIFT SEVERITY & CORRECTION CONFIDENCE — Explainability Infrastructure
  // ============================================================================

  /**
   * Get drift severity for all tracked routes.
   * Shows which pages are chronic drifters, how often they drift,
   * and whether the trend is improving or declining.
   */
  getDriftSeverities: protectedProcedure.query(async () => {
    const severities = await calculateAllDriftSeverities();
    return {
      routes: severities,
      summary: {
        totalTracked: severities.length,
        chronic: severities.filter(s => s.recurrencePattern === 'chronic').length,
        frequent: severities.filter(s => s.recurrencePattern === 'frequent').length,
        occasional: severities.filter(s => s.recurrencePattern === 'occasional').length,
        stable: severities.filter(s => s.recurrencePattern === 'none').length,
        avgSeverity: severities.length > 0
          ? Math.round(severities.reduce((sum, s) => sum + s.severityScore, 0) / severities.length)
          : 0,
        declining: severities.filter(s => s.trend === 'declining').map(s => s.route),
        improving: severities.filter(s => s.trend === 'improving').map(s => s.route),
      },
    };
  }),

  /**
   * Get drift severity for a specific route.
   */
  getRouteDriftSeverity: protectedProcedure
    .input(z.object({ route: z.string() }))
    .query(async ({ input }) => {
      const severity = await calculateDriftSeverity(input.route);
      const history = await getBaselineHistory(input.route, 20);
      return {
        severity,
        baselineHistory: history.map(h => ({
          version: h.version,
          contentHash: h.contentHash,
          createdAt: h.createdAt.toISOString(),
          createdBy: h.createdBy,
          isActive: h.isActive,
        })),
      };
    }),

  /**
   * Get correction confidence for all tracked routes.
   * Shows which routes are safe for auto-fix, which need review,
   * and which should be manual-only.
   */
  getCorrectionConfidences: protectedProcedure.query(async () => {
    const confidences = await calculateAllCorrectionConfidences();
    return {
      routes: confidences,
      summary: {
        totalTracked: confidences.length,
        autoFixEligible: confidences.filter(c => c.recommendation === 'auto-fix').length,
        reviewFirst: confidences.filter(c => c.recommendation === 'review-first').length,
        manualOnly: confidences.filter(c => c.recommendation === 'manual-only').length,
        avgConfidence: confidences.length > 0
          ? Math.round(confidences.reduce((sum, c) => sum + c.confidenceScore, 0) / confidences.length)
          : 50,
        highRiskRoutes: confidences
          .filter(c => c.confidenceScore < 40)
          .map(c => ({ route: c.route, score: c.confidenceScore, reverted: c.revertedCorrections })),
      },
    };
  }),

  /**
   * Get correction confidence for a specific route.
   */
  getRouteCorrectionConfidence: protectedProcedure
    .input(z.object({ route: z.string() }))
    .query(async ({ input }) => {
      return await calculateCorrectionConfidence(input.route);
    }),

  /**
   * Get the comprehensive governance health report.
   * Combines drift severity, correction confidence, and time series data
   * into a single dashboard-ready payload.
   */
  getGovernanceHealth: protectedProcedure.query(async () => {
    const [healthReport, watchdogReport] = await Promise.all([
      generateGovernanceHealthReport(),
      Promise.resolve(getWatchdogReport()),
    ]);

    // Combined score: persistence health (70%) + watchdog operational health (30%)
    const watchdogHealthScore = watchdogReport.status === 'healthy' ? 100
      : watchdogReport.status === 'degraded' ? 60
      : 20;
    const combinedScore = Math.round(
      healthReport.overallScore * 0.7 + watchdogHealthScore * 0.3
    );

    return {
      ...healthReport,
      score: combinedScore,
      status: combinedScore >= 80 ? 'healthy' as const
        : combinedScore >= 50 ? 'degraded' as const
        : 'critical' as const,
      watchdog: {
        status: watchdogReport.status,
        activeAlerts: watchdogReport.activeAlerts.length,
        totalChecks: watchdogReport.totalChecks,
        lastCheckAt: watchdogReport.lastCheckAt,
      },
    };
  }),

  /**
   * Get recent drift time series snapshots for trend visualization.
   */
  getDriftTimeSeries: protectedProcedure
    .input(z.object({ limit: z.number().min(1).max(100).default(30) }).optional())
    .query(async ({ input }) => {
      const snapshots = await getRecentDriftSnapshots(input?.limit || 30);
      return snapshots.map(s => ({
        snapshotId: s.snapshotId,
        truthDriftScore: s.truthDriftScore,
        totalPages: s.totalPages,
        passedPages: s.passedPages,
        flaggedPages: s.flaggedPages,
        blockedPages: s.blockedPages,
        totalViolations: s.totalViolations,
        criticalViolations: s.criticalViolations,
        trend: s.trend,
        weekOverWeekDelta: s.weekOverWeekDelta,
        capturedAt: s.capturedAt.toISOString(),
      }));
    }),

  // =========================================================================
  // TYPOGRAPHY GOVERNANCE
  // =========================================================================

