    const typography = runStaticTypographyScan();
    const accessibility = runStaticAccessibilityScan();
    const freshness = runStaticFreshnessScan();
    const completeness = runStaticCompletenessScan();
    const brandVoice = runStaticBrandVoiceScan();

    const domains = [
      { name: 'typography', score: typography.designSystemCompliance, violations: typography.totalViolations, pages: typography.pagesWithViolations.length },
      { name: 'accessibility', score: accessibility.wcagCompliance.overall, violations: accessibility.totalViolations, pages: accessibility.pagesWithViolations.length },
      { name: 'freshness', score: freshness.freshnessScore, violations: freshness.totalViolations, pages: freshness.pagesWithViolations.length },
      { name: 'completeness', score: completeness.completenessScore, violations: completeness.totalViolations, pages: completeness.pagesWithViolations.length },
      { name: 'brandVoice', score: brandVoice.voiceConsistencyScore, violations: brandVoice.totalViolations, pages: brandVoice.pagesWithViolations.length },
    ];

    const overallScore = Math.round(domains.reduce((sum, d) => sum + d.score, 0) / domains.length);
    const totalViolations = domains.reduce((sum, d) => sum + d.violations, 0);

    return {
      overallScore,
      totalViolations,
      domains,
      status: overallScore >= 80 ? 'healthy' as const : overallScore >= 50 ? 'degraded' as const : 'critical' as const,
    };
