  // ============================================================================
  // PER-ENDPOINT USAGE BREAKDOWN — domain-level scan tracking
  // ============================================================================
  getUsageBreakdown: protectedProcedure
    .input(z.object({
      days: z.number().min(1).max(90).default(30),
    }).optional())
    .query(async ({ ctx, input }) => {
      const userId = ctx.user?.id ?? null;
      if (!userId) return { byEndpoint: [], byDay: [], total: 0 };
      const days = input?.days || 30;
      const rawUsage = await getUsageByUserId(userId, days);

      // Aggregate by endpoint
      const endpointMap: Record<string, { endpoint: string; totalScans: number; lastUsed: string }> = {};
      let total = 0;
      for (const row of rawUsage) {
        const ep = row.endpoint || 'unknown';
        const count = row.callCount || 0;
        total += count;
        if (!endpointMap[ep]) {
          endpointMap[ep] = { endpoint: ep, totalScans: 0, lastUsed: '' };
        }
        endpointMap[ep].totalScans += count;
        const rowDate = new Date(row.date).toISOString();
        if (!endpointMap[ep].lastUsed || rowDate > endpointMap[ep].lastUsed) {
          endpointMap[ep].lastUsed = rowDate;
        }
      }

      // Friendly endpoint names
      const endpointNames: Record<string, string> = {
        review: 'Content Review',
        batch_review: 'Batch Review',
        quick_check: 'Quick Check',
        conversation_review: 'Conversation Review',
        rewrite: 'Content Rewrite',
        quickScan: 'Governance Scan',
        previewAutoFix: 'Auto-Fix Preview',
        executeAutoFix: 'Auto-Fix Execution',
      };

      const byEndpoint = Object.values(endpointMap)
        .map(ep => ({
          ...ep,
          displayName: endpointNames[ep.endpoint] || ep.endpoint.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
          percentage: total > 0 ? Math.round((ep.totalScans / total) * 100) : 0,
        }))
        .sort((a, b) => b.totalScans - a.totalScans);

      // Aggregate by day with endpoint breakdown
      const dayMap: Record<string, Record<string, number>> = {};
      for (const row of rawUsage) {
        const dateKey = new Date(row.date).toISOString().split('T')[0];
        const ep = row.endpoint || 'unknown';
        if (!dayMap[dateKey]) dayMap[dateKey] = {};
        dayMap[dateKey][ep] = (dayMap[dateKey][ep] || 0) + (row.callCount || 0);
      }

      const byDay = Object.entries(dayMap)
        .map(([date, endpoints]) => ({ date, ...endpoints, total: Object.values(endpoints).reduce((s, v) => s + v, 0) }))
        .sort((a, b) => a.date.localeCompare(b.date));

      return { byEndpoint, byDay, total };
    }),

  // ============================================================================
  // PROJECTED EXHAUSTION — when will the user hit their limit?
  // ============================================================================
  getProjectedExhaustion: protectedProcedure
    .query(async ({ ctx }) => {
      const userId = ctx.user?.id ?? null;
      if (!userId) {
        return calculateProjectedExhaustion(0, 3, false, []);
      }
      const usage = await getScanUsageInfo(userId);
      const rawUsage = await getUsageByUserId(userId, 14);

      // Build daily usage array
      const dailyMap: Record<string, number> = {};
      for (const row of rawUsage) {
        const dateKey = new Date(row.date).toISOString().split('T')[0];
        dailyMap[dateKey] = (dailyMap[dateKey] || 0) + (row.callCount || 0);
      }
      const now = new Date();
      const dailyUsage: Array<{ date: string; scans: number }> = [];
      for (let i = 13; i >= 0; i--) {
        const d = new Date(now);
        d.setDate(d.getDate() - i);
        const dateKey = d.toISOString().split('T')[0];
        dailyUsage.push({ date: dateKey, scans: dailyMap[dateKey] || 0 });
      }

      return calculateProjectedExhaustion(
        usage.scansUsed,
        usage.scansLimit,
        usage.isUnlimited,
        dailyUsage,
      );
    }),

