      const userOrg = await getUserOrganization(userId);
      if (!userOrg) throw new TRPCError({ code: 'NOT_FOUND', message: 'No organization found' });
      if (!canManageTeam(userOrg.role)) {
        throw new TRPCError({ code: 'FORBIDDEN', message: 'Only admins can send invitations' });
      }
      const planKey = await getUserPlanKey(userId);
      try {
        const result = await sendInvitation(userOrg.org.id, input.email, input.role, userId, planKey);

        // Send invitation email via Postmark
        const inviterName = ctx.user?.name || 'A team admin';
        const baseUrl = ctx.req?.headers?.origin || process.env.VITE_APP_URL || undefined;
        const expiresAt = new Date();
        expiresAt.setDate(expiresAt.getDate() + 7);

        sendInvitationEmail({
          recipientEmail: input.email,
          inviterName,
          orgName: userOrg.org.name,
          role: input.role,
          token: result.token,
          expiresAt,
        }, baseUrl).catch(err => {
          governanceLog.error('[sendTeamInvitation] Email send failed (non-blocking):', err);
        });

        return { success: true, invitationId: result.invitationId };
      } catch (error: unknown) {
        throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
      }
    }),

  /** Get all invitations for the user's organization */
  getTeamInvitations: protectedProcedure
    .query(async ({ ctx }) => {
      const userId = ctx.user?.id;
      if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
      const userOrg = await getUserOrganization(userId);
      if (!userOrg) return [];
      return getOrgInvitations(userOrg.org.id);
    }),

  /** Revoke a pending invitation */
  revokeTeamInvitation: protectedProcedure
    .input(z.object({
      invitationId: z.number(),
    }))
    .mutation(async ({ ctx, input }) => {
      const userId = ctx.user?.id;
      if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
      const userOrg = await getUserOrganization(userId);
      if (!userOrg) throw new TRPCError({ code: 'NOT_FOUND', message: 'No organization found' });
      if (!canManageTeam(userOrg.role)) {
        throw new TRPCError({ code: 'FORBIDDEN', message: 'Only admins can revoke invitations' });
      }
      try {
        await revokeInvitation(input.invitationId, userOrg.org.id, userId);
        return { success: true };
      } catch (error: unknown) {
        throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
      }
    }),

  /** Accept a team invitation by token */
  acceptTeamInvitation: protectedProcedure
    .input(z.object({
      token: z.string(),
    }))
    .mutation(async ({ ctx, input }) => {
      const userId = ctx.user?.id;
      if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
      try {
        const result = await acceptInvitation(input.token, userId);
        return { success: true, orgId: result.orgId, role: result.role };
      } catch (error: unknown) {
        throw new TRPCError({ code: 'BAD_REQUEST', message: error.message });
      }
    }),

  /** Get seat allocation for the user's organization */
  getTeamSeatAllocation: protectedProcedure
    .query(async ({ ctx }) => {
      const userId = ctx.user?.id;
      if (!userId) throw new TRPCError({ code: 'UNAUTHORIZED' });
      const userOrg = await getUserOrganization(userId);
      if (!userOrg) return null;
      const planKey = await getUserPlanKey(userId);
      return getSeatAllocation(userOrg.org.id, planKey);
    }),

  // ========================================================================
  // INVITATION LOOKUP (public — used by /join/:token page)
  // ========================================================================

  /** Look up an invitation by token (public, for the join page) */
  lookupInvitation: publicProcedure
    .input(z.object({ token: z.string() }))
    .query(async ({ input }) => {
      // D-120: shared singleton (was dynamic import + per-call drizzle()).
      const { sharedDrizzleDb } = await import('../_core/db-singleton');
      const { eq, and } = await import('drizzle-orm');
      const { teamInvitations, organizations } = await import('../../drizzle/schema');
      const db = sharedDrizzleDb();

      const [invitation] = await db
        .select({
          id: teamInvitations.id,
          email: teamInvitations.email,
          role: teamInvitations.role,
          status: teamInvitations.status,
          expiresAt: teamInvitations.expiresAt,
          orgId: teamInvitations.orgId,
        })
        .from(teamInvitations)
        .where(eq(teamInvitations.token, input.token))
        .limit(1);

      if (!invitation) return null;

      // Get org name
      const [org] = await db
        .select({ name: organizations.name })
        .from(organizations)
        .where(eq(organizations.id, invitation.orgId))
        .limit(1);

      const expiresAt = invitation.expiresAt instanceof Date ? invitation.expiresAt : new Date(String(invitation.expiresAt));
      const isExpired = expiresAt < new Date();

      return {
        email: invitation.email,
        role: invitation.role,
        status: isExpired && invitation.status === 'pending' ? 'expired' as const : invitation.status,
        orgName: org?.name || 'Unknown Organization',
        expiresAt: expiresAt.toISOString(),
      };
    }),

  // ========================================================================
  // CLAUDE AUTO-RESOLVER ADMIN ENDPOINTS
  // ========================================================================

  /** Get Claude auto-resolver stats */
  getResolverStats: protectedProcedure
    .query(async () => {
      const stats = getResolverStats();
      const dbStats = await getResolutionDbStats();
      return { ...stats, dbStats };
    }),

  /** Get recent resolution log entries */
  getRecentResolutions: protectedProcedure
    .input(z.object({ limit: z.number().min(1).max(100).default(50) }).optional())
    .query(async ({ input }) => {
      return getRecentResolutions(input?.limit || 50);
    }),

  /** Manually trigger the weekly resolution digest */
  triggerWeeklyDigest: protectedProcedure
    .input(z.object({ email: z.string().email() }))
    .mutation(async ({ input }) => {
      return runWeeklyDigest(input.email);
    }),

  /** Get weekly resolution digest scheduler status */
  getResolutionDigestStatus: protectedProcedure
    .query(async () => {
      return getDigestSchedulerStatus();
    }),

  /** Preview digest data without sending */
  previewWeeklyDigest: protectedProcedure
    .query(async () => {
      return gatherDigestData();
    }),

  // ========================================================================
  // CONTENT INTELLIGENCE (Unified: Narrative + Journey + Digestibility)
  // ========================================================================
  /** Get Content Intelligence composite score and dimension breakdown (public for /content-intelligence page) */
  getContentIntelligence: publicProcedure.query(async () => {
    return await calculateContentIntelligence();
  }),

  /** Get Content Intelligence trend data for charts */
  getContentIntelligenceTrend: publicProcedure
    .input(z.object({
      timeRange: z.enum(['7d', '30d', '90d']).default('7d')
    }).optional())
    .query(async ({ input }) => {
      const timeRange = input?.timeRange || '7d';
      return getDigestibilityTrend(timeRange);
    }),

  /** Get Content Intelligence summary for badges and quick displays */
  getContentIntelligenceSummary: publicProcedure.query(async () => {
    return await getContentIntelligenceSummary();
  }),

  // ========================================================================
  // POLICY CONSTRAINT ENGINE (PCE) — CRUD & Management
  // ========================================================================

  /** List all active policies */
  pceListPolicies: protectedProcedure.query(() => {
    return {
      policies: pceGetActivePolicies(),
      stats: pceGetRegistryStats(),
    };
  }),

  /** Create or update a policy */
  pceUpsertPolicy: adminProcedure
    .input(z.object({
      id: z.string().min(1),
      name: z.string().min(1),
      description: z.string(),
      severity: z.enum(['critical', 'high', 'medium', 'low']),
      surfaces: z.array(z.string()),
      conditions: z.array(z.object({
        type: z.string(),
        operator: z.enum(['AND', 'OR', 'NOT']).optional(),
        threshold: z.number().optional(),
        pattern: z.string().optional(),
        children: z.array(z.any()).optional(),
      })),
      action: z.enum(['BLOCK_PATCH', 'ESCALATE_FINDING', 'REQUIRE_APPROVAL', 'LOG_ONLY', 'AUTO_PATCH_OVERRIDE']),
      enabled: z.boolean().default(true),
    }))
    .mutation(({ input }) => {
      const policy: PolicyDefinition = {
        id: input.id,
        name: input.name,
        description: input.description,
        severity: input.severity as PolicySeverity,
        surfaces: input.surfaces,
        conditions: input.conditions as PolicyCondition[],
        action: input.action as PolicyAction,
        enabled: input.enabled,
      };
      pceUpsertPolicy(policy);
      return { success: true, policy };
    }),

  /** Toggle a policy on/off */
  pceTogglePolicy: adminProcedure
    .input(z.object({
      policyId: z.string(),
      enabled: z.boolean(),
    }))
    .mutation(({ input }) => {
      pceTogglePolicy(input.policyId, input.enabled);
      return { success: true, policyId: input.policyId, enabled: input.enabled };
    }),

  /** Remove a policy */
  pceRemovePolicy: adminProcedure
    .input(z.object({ policyId: z.string() }))
    .mutation(({ input }) => {
      const removed = pceRemovePolicy(input.policyId);
      return { success: removed, policyId: input.policyId };
    }),

  /** Reset all policies to defaults */
  pceResetPolicies: adminProcedure
    .mutation(() => {
      pceResetToDefaults();
      return { success: true, policies: pceGetActivePolicies() };
    }),

  /** Get PCE compliance trend */
  pceGetComplianceTrend: protectedProcedure.query(() => {
    return {
      trend: getComplianceTrend(),
      history: getPCEHistory().map((r, i) => ({
        cycle: i + 1,
        compliance: r.complianceScore,
        violations: r.evaluation.violations.length,
        patchesBlocked: r.enforcement.patchesBlocked,
        patchesSurvived: r.patchesSurvived,
        policiesTriggered: r.evaluation.policiesTriggered,
      })),
    };
  }),

  /** Get PCE violation summary */
  pceGetViolationSummary: protectedProcedure.query(() => {
    return getViolationSummary();
  }),

  /** Get auto-tuner configuration */
  pceGetAutoTunerConfig: protectedProcedure.query(() => {
    return {
      config: getAutoTunerConfig(),
      latestTuning: getLatestTuning(),
      history: getTuningHistory().slice(-20),
    };
  }),

  /** Update auto-tuner configuration */
  pceUpdateAutoTunerConfig: adminProcedure
    .input(z.object({
      enabled: z.boolean().optional(),
      minCyclesForTuning: z.number().min(2).max(20).optional(),
      equilibriumComplianceThreshold: z.number().min(50).max(100).optional(),
      equilibriumWindowSize: z.number().min(2).max(10).optional(),
      maxTighteningStep: z.number().min(1).max(25).optional(),
      maxRelaxationStep: z.number().min(1).max(30).optional(),
      degradationComplianceThreshold: z.number().min(20).max(80).optional(),
    }))
    .mutation(({ input }) => {
      const updated = updateAutoTunerConfig(input);
      return { success: true, config: updated };
    }),

  /** Manually trigger auto-tuner */
  pceRunAutoTuner: adminProcedure
    .mutation(() => {
      const result = pceRunAutoTuner();
      return result;
    }),
});

