/**
 * Policy Constraint Engine — Policy DSL Schema
 * 
 * Defines the declarative policy format for system-level governance rules.
 * Policies evaluate system behavior (findings, patches, resources, claims)
 * and enforce constraints across all governance surfaces.
 * 
 * Step 2 of PCE implementation.
 * Created: Mar 9, 2026
 */

// ============================================================================
// SEVERITY LEVELS
// ============================================================================

export type PolicySeverity = 'T1' | 'T2' | 'T3' | 'T4';

export const SEVERITY_WEIGHTS: Record<PolicySeverity, number> = {
  T1: 1.0,   // Critical — immediate action required
  T2: 0.75,  // High — should be addressed within cycle
  T3: 0.5,   // Medium — can be deferred
  T4: 0.25,  // Low — informational
};

// ============================================================================
// POLICY ACTIONS
// ============================================================================

export type PolicyAction =
  | 'BLOCK_PATCH'           // Remove patch from execution queue
  | 'ESCALATE_FINDING'      // Escalate finding to owner notification
  | 'REQUIRE_APPROVAL'      // Hold patch pending manual approval
  | 'LOG_ONLY'              // Record violation but take no action
  | 'AUTO_PATCH_OVERRIDE';  // Force patch application regardless of confidence

// ============================================================================
// CONDITION TYPES
// ============================================================================

export type ConditionType =
  | 'findingType'       // Match finding.type
  | 'resourceType'      // Match resource file extension or pattern
  | 'surface'           // Match finding.surface
  | 'contentMatch'      // Regex match on finding.description
  | 'claimMatch'        // Match narrative claim text
  | 'patchType'         // Match patch type
  | 'patchSize'         // Patch lines changed threshold
  | 'confidenceBelow'   // Patch confidence below threshold
  | 'severityAtLeast'   // Finding severity at or above threshold
  | 'findingCount'      // Count of findings exceeds threshold
  | 'claimContradiction' // Number of claim contradictions
  | 'consistencyBelow'  // Consistency score below threshold
  | 'stabilityBelow'    // Stability score below threshold
  | 'driftAbove';       // Drift score above threshold

export interface PolicyCondition {
  type: ConditionType;
  /** Value to match against — string for pattern matching, number for thresholds */
  value?: string;
  /** Numeric threshold for comparison conditions */
  threshold?: number;
  /** Regex pattern for content matching */
  pattern?: string;
  /** Negate the condition (NOT operator) */
  negate?: boolean;
  /** Field to evaluate */
  field?: string;
  /** Comparison operator */
  operator?: string;
}

// ============================================================================
// LOGICAL OPERATORS
// ============================================================================

export type LogicalOperator = 'AND' | 'OR';

// ============================================================================
// POLICY DEFINITION
// ============================================================================

export interface PolicyDefinition {
  /** Unique policy identifier */
  id: string;
  /** Human-readable description */
  description: string;
  /** Which surfaces this policy applies to (empty = all surfaces) */
  surfaces: string[];
  /** Conditions that must be met for the policy to trigger */
  conditions: PolicyCondition[];
  /** Logical operator for combining conditions (default: AND) */
  operator?: LogicalOperator;
  /** Action to take when policy is violated */
  action: PolicyAction;
  /** Severity level of the violation */
  severity: PolicySeverity;
  /** Whether this policy is currently active */
  enabled: boolean;
  /** Policy category for grouping */
  category?: string;
  /** Tags for filtering */
  tags?: string[];
  /** Creation timestamp */
  createdAt?: number;
  /** Last modified timestamp */
  updatedAt?: number;
}

// ============================================================================
// POLICY VIOLATION
// ============================================================================

export interface PolicyViolation {
  /** The policy that was violated */
  policyId: string;
  /** Severity of the violation */
  severity: PolicySeverity;
  /** Surface where the violation occurred */
  surface: string;
  /** Resource involved */
  resource: string;
  /** Human-readable description of the violation */
  description: string;
  /** Action taken in response */
  action: PolicyAction;
  /** Whether the action was successfully enforced */
  enforced: boolean;
  /** The finding that triggered the violation (if applicable) */
  findingId?: string;
  /** The patch that was affected (if applicable) */
  patchId?: string;
  /** Timestamp of the violation */
  timestamp: number;
  /** Stable fingerprint for deduplication across cycles */
  fingerprint?: string;
  /** Additional context */
  context?: Record<string, any>;
}

// ============================================================================
// POLICY EVALUATION CONTEXT
// ============================================================================

export interface PolicyEvaluationContext {
  /** All findings from the current governance cycle */
  findings: Array<{
    id: string;
    type: string;
    surface: string;
    resource: string;
    description: string;
    severity?: string;
    tier?: number;
    confidence?: number;
  }>;
  /** All patches generated in the current cycle */
  patches: Array<{
    findingId: string;
    resource: string;
    type: string;
    tier?: number;
    confidence: number;
    linesChanged?: number;
  }>;
  /** Resources scanned */
  resources: Array<{
    id: string;
    surface: string;
    location: string;
  }>;
  /** Narrative claims (if available) */
  claims?: Array<{
    claimText: string;
    page: string;
    section: string;
    confidence: number;
  }>;
  /** System metrics */
  metrics?: {
    consistencyScore?: number;
    stabilityScore?: number;
    driftScore?: number;
    findingCount?: number;
    patchSuccessRate?: number;
  };
}

// ============================================================================
// POLICY EVALUATION RESULT
// ============================================================================

export interface PolicyEvaluationResult {
  /** Total policies evaluated */
  policiesEvaluated: number;
  /** Policies that triggered violations */
  policiesTriggered: number;
  /** All violations detected */
  violations: PolicyViolation[];
  /** Patches blocked by policy */
  patchesBlocked: string[];
  /** Findings escalated by policy */
  findingsEscalated: string[];
  /** Patches requiring approval */
  patchesPendingApproval: string[];
  /** Compliance score (0-100) */
  complianceScore: number;
  /** Evaluation timestamp */
  evaluatedAt: number;
  /** Duration of evaluation in ms */
  evaluationDurationMs: number;
}

